def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color in (0,2,4): continue
            for dr,dc in ((0,1),(1,0)):
                rr,cc=r+dr,c+dc
                while rr<h and cc<w:
                    if grid[rr][cc]==color:
                        y,x=r+dr,c+dc
                        while (y,x)!=(rr,cc):
                            if out[y][x]==0: out[y][x]=color
                            y+=dr; x+=dc
                        break
                    rr+=dr; cc+=dc
    return out

